-- Source: FED_IRS_AUTO_REVOCATIONS (1,207,295 rows)  [row count re-verified against the live table 2026-08-11; header had said 500000]
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: REVOCATION_DATE/REVOCATION_POSTING_DATE/REINSTATEMENT_DATE
-- were bare try_to_date() calls -- a pure-digit value would misread as epoch
-- seconds instead of failing safely. Now reads the already-guarded staging
-- model (same 12 columns, same order, same three dates via stg_date's
-- separator guard); its own dedupe drops only exact whole-row duplicates
-- (documented there: EIN alone isn't unique, ~19K of 1.2M rows), it doesn't
-- change anything the mart's select was actually returning.

select
    ein,
    legal_name,
    doing_business_as,
    organization_address,
    city,
    state,
    zip_code,
    country,
    exemption_type,
    revocation_date,
    revocation_posting_date,
    reinstatement_date
from {{ ref('stg_fed_irs_auto_revocations__organizations') }}
